/* @lc app=leetcode id=3882 lang=kotlin */ class Solution { fun minCost(grid: Array<IntArray>): Int = grid[0].size.let { n -> grid.indices.fold(Array(n) { BooleanArray(1024) }) { prev, i -> Array(n) { BooleanArray(1024) }.also { cur -> (0 until n).forEach { j -> (0 until 1024).forEach { x -> cur[j][x] = if (i == 0 && j == 0) x == grid[0][0] else ((i > 0 && prev[j][x xor grid[i][j]]) || (j > 0 && cur[j - 1][x xor grid[i][j]])) } } } }.last().let { r -> (0 until 1024).first { r[it] } } } }